export const getGetModelUsageUrl = (
  organizationId: string,
  params?: GetModelUsageParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/model-usage?${stringifiedParams}`
    : `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/model-usage`;
};

