export const getCheckSetupUrl = (organizationId: string) => {
  return `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/setup-checklist/check`;
};

/**
 * Ask Intelligence, the model provider and the computers again, then return the checklist as getSetupChecklist does.
 * @summary Check the setup again
 */
export const checkSetup = async (
  organizationId: string,
  headers: CheckSetupHeaders,
  options?: Parameters<typeof apiRequest>[1],
): Promise<SetupChecklist> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<SetupChecklist>(getCheckSetupUrl(organizationId), {
    ...options,
    method: "POST",
    headers: { ...headers, ...getHeaders(options?.headers) },
  });
};

export const getCheckSetupMutationKey = () => ["checkSetup"] as const;

export const getCheckSetupMutationOptions = <
  TError =
    | InvalidRequestResponse
    | UnauthenticatedResponse
    | ForbiddenResponse
    | OrganizationNotFoundResponse
    | IdempotencyConflictResponse
    | ServerErrorResponse
    | UnexpectedErrorResponse,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof checkSetup>>,
    TError,
    CheckSetupMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof apiRequest>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof checkSetup>>,
  TError,
  CheckSetupMutationVariables,
  TContext
> => {
  const mutationKey = getCheckSetupMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof checkSetup>>,
    CheckSetupMutationVariables
  > = (props) => {
    const { organizationId, headers } = props ?? {};

    return checkSetup(organizationId, headers, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CheckSetupMutationResult = NonNullable<
  Awaited<ReturnType<typeof checkSetup>>
>;

export type CheckSetupMutationError =
  | InvalidRequestResponse
  | UnauthenticatedResponse
  | ForbiddenResponse
  | OrganizationNotFoundResponse
  | IdempotencyConflictResponse
  | ServerErrorResponse
  | UnexpectedErrorResponse;
export type CheckSetupMutationVariables = {
  organizationId: string;
  headers: CheckSetupHeaders;
};

